#!/usr/bin/env bash
set -euo pipefail
PROJECT_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)";BUILD_ROOT="$PROJECT_ROOT/build/sm64-modern-horizontal-grindel";mkdir -p "$BUILD_ROOT/module-cache"
xcrun swiftc -parse-as-library -swift-version 6 -Xfrontend -strict-concurrency=complete -module-cache-path "$BUILD_ROOT/module-cache" "$PROJECT_ROOT/SM64Modern/HorizontalGrindelBehavior.swift" "$PROJECT_ROOT/tests/sm64_modern_horizontal_grindel_smoke.swift" -o "$BUILD_ROOT/smoke";swift_output="$($BUILD_ROOT/smoke)";printf '%s\n' "$swift_output";xcrun clang -std=c11 "$PROJECT_ROOT/tests/sm64_modern_horizontal_grindel_contract.c" -o "$BUILD_ROOT/contract";c_output="$($BUILD_ROOT/contract)";printf '%s\n' "$c_output";s="$(printf '%s\n' "$swift_output"|sed -n 's/^horizontalGrindelFingerprint=//p')";c="$(printf '%s\n' "$c_output"|sed -n 's/^horizontalGrindelFingerprint=//p')";[[ -n "$s"&&"$s" == "$c" ]]||{ echo "horizontal Grindel mismatch Swift=$s C=$c" >&2;exit 1;};printf '%s\n' 'Swift/C horizontal Grindel contract matched'
